import numpy as np
import numba as nb

@nb.njit(cache=True)
def _lap(c):
    n=c.shape[0]; price=np.zeros(n); owner=np.full(n,-1,np.int32); ass=np.full(n,-1,np.int32)
    eps=.25
    while eps>1e-12:
        owner[:]=-1; ass[:]=-1
        stack=np.arange(n,dtype=np.int32); top=n
        while top:
            top-=1; i=stack[top]
            best=1e100; second=1e100; bj=-1
            for j in range(n):
                x=c[i,j]+price[j]
                if x<best: second=best; best=x; bj=j
                elif x<second: second=x
            price[bj]+=second-best+eps
            old=owner[bj]; owner[bj]=i; ass[i]=bj
            if old>=0: stack[top]=old; top+=1
        eps*=.1
    return ass

class Solver:
    def solve(self, problem, **kwargs):
        a=np.asarray(problem['source_weights']); b=np.asarray(problem['target_weights'])
        c=np.asarray(problem['cost_matrix']); n=len(a)
        if n==len(b) and np.all(a==a[0]) and np.all(b==b[0]) and a[0]==b[0]:
            ass=_lap(c)
            g=np.zeros(c.shape); g[np.arange(n),ass]=a
            return {'transport_plan':g}
        import ot
        return {'transport_plan':ot.lp.emd(a,b,np.ascontiguousarray(c,dtype=np.float64),check_marginals=False)}

